-- Permanent learner codes: generated by PostgreSQL, never by the browser.
-- Format: CH + gender initial + two-digit Kampala admission year + global sequence.
create sequence if not exists public.student_admission_sequence
  as bigint
  start with 1
  increment by 1
  no cycle;

alter table public.students
  add column if not exists admission_year smallint;

update public.students
set admission_year = extract(year from created_at at time zone 'Africa/Kampala')::smallint
where admission_year is null;

alter table public.students
  alter column admission_year set not null;

grant usage, select on sequence public.student_admission_sequence to authenticated;

create or replace function public.assign_permanent_learner_code()
returns trigger
language plpgsql
security invoker
set search_path = ''
as $function$
declare
  v_year integer;
  v_gender_code text;
  v_sequence bigint;
begin
  v_year := extract(year from pg_catalog.timezone('Africa/Kampala', now()))::integer;

  v_gender_code := case new.gender
    when 'Male' then 'M'
    when 'Female' then 'F'
    else 'X'
  end;

  v_sequence := pg_catalog.nextval('public.student_admission_sequence'::regclass);

  new.admission_year := v_year;
  new.admission_number := 'CH' || v_gender_code || pg_catalog.right(v_year::text, 2)
    || '-' || pg_catalog.lpad(v_sequence::text, 6, '0');

  return new;
end;
$function$;

create or replace function public.prevent_permanent_learner_code_change()
returns trigger
language plpgsql
security invoker
set search_path = ''
as $function$
begin
  if new.admission_number is distinct from old.admission_number
     or new.admission_year is distinct from old.admission_year then
    raise exception 'The permanent learner code and admission year cannot be changed';
  end if;
  return new;
end;
$function$;

drop trigger if exists students_assign_permanent_code on public.students;
create trigger students_assign_permanent_code
before insert on public.students
for each row execute function public.assign_permanent_learner_code();

drop trigger if exists students_prevent_permanent_code_change on public.students;
create trigger students_prevent_permanent_code_change
before update on public.students
for each row execute function public.prevent_permanent_learner_code_change();

revoke all on function public.assign_permanent_learner_code() from public, anon, authenticated;
revoke all on function public.prevent_permanent_learner_code_change() from public, anon, authenticated;
